function tab(name){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===name));$('pageTitle').textContent={review:'Every touch tells a story.',dashboard:'Patterns you can act on.',clips:'Keep the moments that matter.'}[name];render()}
