function roleFields(){const p=$('position').value,def=['Libero','Defensive specialist'].includes(p);$('roleFields').innerHTML=p==='Setter'?'<div class="fields">'+selectField('destination','Set destination',['Unknown','Outside','Middle','Opposite','Back row','Setter attack'])+selectField('quality','Set quality',['Unknown','In rhythm','Hittable with adjustment','Unattackable'])+'</div><div class="fields">'+selectField('tempo','Trajectory / tempo',['Unknown','High arc','Medium arc','Quick / flat'])+selectField('placement','Net distance',['Unknown','Tight','On target','Too far off'])+'</div>':selectField('action','Action',def?['Serve receive','Defense','Serve','Emergency set']:['Attack','Block','Serve','Serve receive','Defense'])+selectField('quality','Contact quality',['Unknown','Controlled','Playable','Error']);$('outcome').innerHTML=(def?reception:['Unknown','Kill','Dug by opponent','Blocked back into play','Blocked for point','Attack error','Setter fault','Ace','Serve in play','Serve error','Block point','Block touch','No block touch','Controlled dig','Uncontrolled dig','Ball down','In-system pass','Playable pass','Overpass','Reception error']).map(v=>`<option>${v}</option>`).join('');if(p==='Setter')$('outcome').innerHTML=outcomes.map(v=>`<option>${v}</option>`).join('');for(const label of ['Ace','Serve in play','Serve error'])if(!Array.from($('outcome').options||[]).some(o=>o.value===label))$('outcome').innerHTML+='<option>'+label+'</option>';$('mishit').parentElement.hidden=def}
