const openDB=new Promise(resolve=>{const req=indexedDB.open('courtsense-media',2);req.onupgradeneeded=()=>{for(const name of ['videos','tracks'])if(!req.result.objectStoreNames.contains(name))req.result.createObjectStore(name,{keyPath:'id'})};req.onsuccess=()=>{db=req.result;resolve(db)};req.onerror=()=>resolve(null)});
function storeMedia(m){return new Promise((resolve,reject)=>{if(!db)return reject(Error('Storage unavailable'));const tx=db.transaction('videos','readwrite');tx.objectStore('videos').put(m);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
