video.onplay=()=>{$('play').textContent='Ⅱ Pause'};video.onpause=()=>{$('play').textContent='▶ Play'};
async function play(){try{await video.play()}catch{toast('Import a playable video first.')}}
$('play').onclick=()=>{if(!media)return toast('Import a video first.');video.paused?play():video.pause()};
$('back').onclick=()=>{if(media)video.currentTime=Math.max(0,video.currentTime-3)};$('forward').onclick=()=>{if(media)video.currentTime=Math.min(video.duration,video.currentTime+3)};$('speed').onchange=()=>video.playbackRate=Number($('speed').value);
