async function loadPlay(id,edit=false){const p=plays.find(x=>x.id===id);if(!p)return;if(p.sample)return toast('Sample play only. Import your footage to review real video clips.');if(media?.id!==p.mediaId){const m=await getMedia(p.mediaId);if(!m)return toast('Original video is not available on this device. Your tags are intact.');setMedia(m);await new Promise(resolve=>video.addEventListener('loadedmetadata',resolve,{once:true}))}tab('review');$('start').value=p.start;$('end').value=p.end;points=p.points||[];drawTrace();video.currentTime=p.start;clipEnd=p.end;globalThis.reviewTools?.restoreTags(p);if(edit){editing=p.id;$('player').value=p.player;$('position').value=p.position;roleFields();for(const key of ['outcome','quality','destination','tempo','placement','action','pass','blockers','notes'])if($(key))$(key).value=p[key]||'';$('mishit').checked=p.mishit;$('save').textContent='Save changes';$('cancel').hidden=false}else{editing=null;$('save').textContent='Save play & clip ＋';$('cancel').hidden=true;const [a,b]=globalThis.reviewTools?.bounds(p,video.duration)||[p.start,p.end];video.currentTime=a;clipEnd=b;await play()}window.scrollTo({top:0,behavior:'smooth'})}
function cards(list){return list.length?list.map(p=>`<article class="clip-card"><button class="clip-top" data-open="${p.id}" aria-label="Play clip at ${time(p.start)}"><span>${p.sample?'SAMPLE DATA':time(p.start)+' → '+time(p.end)}</span><b>${esc((p.suggested?'Suggested · ':'')+(p.outcome==='Unknown'&&p.detected?p.detected:p.outcome))}</b></button><div class="clip-content"><h3>${esc(p.player)} <span class="muted">/ ${esc(p.position)}</span></h3><p>${(globalThis.reviewTools?.kinds(p)||[]).map(esc).join(' · ')} ${p.setterZone?' · Setter Z'+esc(p.setterZone):''}</p><p>${esc(p.destination||p.action)} · ${esc(p.quality)}</p><p>${esc(p.notes||'No coaching note yet.')}</p><p>${p.mishit?'Mishit tagged · ':''}${(p.end-p.start).toFixed(1)}s clip${p.points?.length?' · Trajectory traced':''}</p>${globalThis.keeper?.card(p)||''}${globalThis.reviewTools?.serveControl(p)||''}<div class="clip-actions"><button data-open="${p.id}">▷ Review</button><button data-edit="${p.id}">Edit</button><button data-export="${p.id}" ${p.sample?'disabled':''}>Download clip</button><button data-delete="${p.id}" class="danger" aria-label="Delete play for ${esc(p.player)}">Delete</button></div></div></article>`).join(''):'<div class="empty-list">No plays here yet. Import footage and save a tagged moment to begin.</div>'}
function selected(){return plays.filter(p=>!p.suggested&&(globalThis.keeper?.statsMatch(p)??true)&&(!$('filterPlayer').value||p.player===$('filterPlayer').value)&&(!$('filterPosition').value||p.position===$('filterPosition').value))}
function bars(items,total,click=false){return Object.entries(items).map(([name,n])=>`<button class="bar-row" ${click?`data-outcome="${esc(name)}"`: 'tabindex="-1"'} aria-label="${esc(name)}: ${n} plays"><span>${esc(name)}</span><div class="bar-track"><div class="bar" style="width:${total?n/total*100:0}%"></div></div><b>${n}</b></button>`).join('')||'<p class="hint">Tag plays to build this chart.</p>'}
const countBy=(list,key)=>list.reduce((a,p)=>(a[p[key]]=(a[p[key]]||0)+1,a),{});
function render(){globalThis.keeper?.stats();const selectedPlayer=$('filterPlayer').value;$('filterPlayer').innerHTML='<option value="">All players</option>'+[...new Set(plays.map(p=>p.player))].sort().map(p=>`<option>${esc(p)}</option>`).join('');$('filterPlayer').value=selectedPlayer;const list=selected(),sets=list.filter(p=>p.position==='Setter'&&!['Ace','Serve error','Serve in play'].includes(p.outcome)),known=sets.filter(p=>p.quality!=='Unknown'),attackOutcomes=['Kill','Dug by opponent','Blocked back into play','Blocked for point','Attack error'],attacks=sets.filter(p=>attackOutcomes.includes(p.outcome)),kills=attacks.filter(p=>p.outcome==='Kill').length,hit=known.filter(p=>['In rhythm','Hittable with adjustment'].includes(p.quality)).length;const metric=(title,value,sub)=>`<div class="metric"><span>${title}</span><strong>${value}</strong><small>${sub}</small></div>`;$('metrics').innerHTML=metric('Tagged plays',list.length,sample?'Illustrative sample data':'Current player / position filter')+metric('Kill rate off sets',attacks.length?Math.round(kills/attacks.length*100)+'%':'—',`${kills} kills / ${attacks.length} known attacks`)+metric('Hittable sets',known.length?Math.round(hit/known.length*100)+'%':'—',`${hit} hittable / ${known.length} graded sets`)+metric('Needs outcome review',list.filter(p=>p.outcome==='Unknown').length,'Unknown outcomes stay out of rates');$('outcomeChart').innerHTML=bars(countBy(list,'outcome'),list.length,true);$('distribution').innerHTML=bars(countBy(sets,'destination'),sets.length);$('insight').textContent=sets.length?`${sets.length} setter plays tagged. ${sets.filter(p=>p.placement==='Tight').length} marked tight to the net. Review those clips for hitter adjustments and block pressure.`:'Start with one player and a few rallies. Consistent tagging will make the patterns useful.';$('recent').innerHTML=cards(plays.slice(-3).reverse());$('evidence').innerHTML=cards(list.filter(p=>!activeOutcome||p.outcome===activeOutcome));$('evidenceTitle').textContent=activeOutcome?`Clips: ${activeOutcome}`:'Supporting clips';const q=$('search').value.toLowerCase();$('library').innerHTML=(globalThis.reviewTools?.groupedCards||cards)(plays.filter(p=>[p.player,p.position,p.notes,p.outcome].join(' ').toLowerCase().includes(q)&&(globalThis.reviewTools?.matches(p)??true)&&(globalThis.keeper?.matches(p)??true)).slice().reverse());$('sourceBadge').textContent=sample?'SAMPLE DATA':media?'YOUR FOOTAGE':'NO VIDEO'}
$('filterPlayer').onchange=render;$('filterPosition').onchange=render;$('search').oninput=render;$('clearOutcome').onclick=()=>{activeOutcome='';render()};$('resetFilters').onclick=()=>{$('filterPlayer').value='';$('filterPosition').value='';activeOutcome='';render()};
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open)loadPlay(b.dataset.open);if(b.dataset.edit)loadPlay(b.dataset.edit,true);if(b.dataset.export)exportClip(b.dataset.export);if(b.dataset.outcome){activeOutcome=b.dataset.outcome;render()}if(b.dataset.delete){const p=plays.find(x=>x.id===b.dataset.delete);if(!confirm('Delete this tagged play? The original video will remain.'))return;plays=plays.filter(x=>x.id!==p.id);if(editing===p.id)resetForm();persist();render();toast('Play deleted.')}});
