$('backup').onclick=()=>download(new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),sample,plays,matchBook:sample?undefined:globalThis.keeper?.exportBook()},null,2)],{type:'application/json'}),'courtsense-analysis.json');
$('demo').onclick=()=>{if(sample){sample=false;plays=realPlays();$('demo').textContent='Explore sample data'}else{sample=true;plays=Array.from({length:12},(_,i)=>({id:uid(),sample:true,player:i%3?'Jordan #7':'Alex #12',position:'Setter',destination:['Outside','Middle','Opposite','Outside'][i%4],quality:i%5===0?'Unattackable':i%3?'In rhythm':'Hittable with adjustment',tempo:'High arc',placement:i%4===0?'Tight':'On target',outcome:['Kill','Dug by opponent','Kill','Blocked for point','Attack error','Unknown'][i%6],start:i*15,end:i*15+6,notes:['Watch the hitter’s approach timing.','Review the distance off the net.','Compare placement with the previous rally.'][i%3],points:[],mishit:i===4}));$('demo').textContent='Exit sample data'}activeOutcome='';render();tab('dashboard');toast(sample?'Sample data is illustrative and separate from your saved plays.':'Returned to your saved analysis.')};
async function exportClip(id){if(busy)return toast('A clip export is already running.');const p=plays.find(p=>p.id===id);if(!p||p.sample)return;await openDB;const m=media?.id===p.mediaId?media:await getMedia(p.mediaId);if(!m)return toast('Original video is unavailable on this device.');if(typeof MediaRecorder==='undefined')return toast('This browser cannot export clips. Use Chrome or Edge on desktop; trimmed playback still works.');busy=true;toast('Rendering your clip in real time. Keep this tab open.');const v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';v.src=URL.createObjectURL(m.blob);let stream,rec,raf,watchdog;try{await new Promise((res,rej)=>{v.onloadedmetadata=res;v.onerror=()=>rej(Error('Video could not load.'))});const [exportStart,exportEnd]=globalThis.reviewTools?.bounds(p,v.duration)||[p.start,p.end];v.currentTime=exportStart;await new Promise(res=>v.addEventListener('seeked',res,{once:true}));v.playbackRate=1;const capture=v.captureStream||v.mozCaptureStream;if(!capture)throw Error('Clip downloads require desktop Chrome or Firefox. You can still preview trimmed clips here.');await v.play();stream=capture.call(v);const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('No supported export format found in this browser.');rec=new MediaRecorder(stream,{mimeType:mime});const chunks=[];const done=new Promise((res,rej)=>{rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=res;rec.onerror=()=>rej(Error('Recording failed.'));watchdog=setTimeout(()=>{if(rec.state!=='inactive')rec.stop();rej(Error('Export timed out. Keep the tab visible and try a shorter clip.'))},(exportEnd-exportStart)*1000+15000)});rec.start(100);const tick=()=>{if(v.currentTime>=exportEnd||v.ended){rec.stop();v.pause()}else raf=requestAnimationFrame(tick)};tick();await done;const blob=new Blob(chunks,{type:mime});if(!blob.size)throw Error('Clip export was empty.');download(blob,`courtsense-${p.player.replace(/[^a-z0-9]/gi,'-')}-${time(p.start).replace(':','-')}.${mime.includes('mp4')?'mp4':'webm'}`);toast('Trimmed clip downloaded. Export is re-encoded in real time; annotations stay in the analysis.')}catch(e){toast(e.message)}finally{clearTimeout(watchdog);cancelAnimationFrame(raf);if(rec&&rec.state!=='inactive')rec.stop();v.pause();stream?.getTracks().forEach(t=>t.stop());URL.revokeObjectURL(v.src);busy=false}}
render();
